def merge_intervals(intervals):
    if not intervals:
        return []

    # Sort intervals by start time
    sorted_intervals = sorted(intervals, key=lambda x: x[0])

    merged = [sorted_intervals[0]]

    for current_start, current_end in sorted_intervals[1:]:
        last_start, last_end = merged[-1]

        if current_start <= last_end:
            # Overlapping or touching intervals - merge them
            merged[-1] = [last_start, max(last_end, current_end)]
        else:
            # Non-overlapping interval - add it to merged list
            merged.append([current_start, current_end])

    return merged

def toposort(nodes, edges):
    # Build adjacency list and in-degree count
    graph = {node: [] for node in nodes}
    in_degree = {node: 0 for node in nodes}

    # Process edges to build graph and track in-degrees
    for source, dest in edges:
        if source == dest:
            raise ValueError("Cycle detected: self loop")
        graph[source].append(dest)
        in_degree[dest] += 1

    # Initialize queue with nodes having zero in-degree
    queue = []
    for node in nodes:
        if in_degree[node] == 0:
            queue.append(node)

    # Sort queue to ensure lexicographical order
    queue.sort()

    result = []

    while queue:
        # Get the smallest node (lexicographically)
        current = queue.pop(0)
        result.append(current)

        # Reduce in-degree of neighbors
        for neighbor in graph[current]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

        # Re-sort queue to maintain lexicographical order
        queue.sort()

    # Check if all nodes were processed (cycle detection)
    if len(result) != len(nodes):
        raise ValueError("Cycle detected")

    return result

def stable_batches(items, limit):
    if limit <= 0:
        raise ValueError("Limit must be positive")

    result = []
    current_batch = []
    current_weight = 0

    for name, weight in items:
        if weight <= 0 or weight > limit:
            raise ValueError("All weights must be positive and not exceed the limit")

        if current_weight + weight > limit:
            if current_batch:
                result.append(current_batch)
            current_batch = []
            current_weight = 0

        current_batch.append(name)
        current_weight += weight

    if current_batch:
        result.append(current_batch)

    return result

import re

def parse_env(text):
    result = {}
    line_pattern = re.compile(r'^([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*)$')

    for line_num, line in enumerate(text.splitlines(), 1):
        line = line.strip()
        if not line or line.startswith('#'):
            continue

        match = line_pattern.match(line)
        if not match:
            raise ValueError(f"Invalid line {line_num}: {line}")

        key, value = match.groups()
        key = key.strip()
        value = value.strip()

        # Strip matching single/double quotes
        if value.startswith('"') and value.endswith('"'):
            value = value[1:-1]
        elif value.startswith("'") and value.endswith("'"):
            value = value[1:-1]

        result[key] = value

    return result

def parse_sse(chunks):
    data_lines = []
    events = []
    buffer = b""

    for chunk in chunks:
        buffer += chunk

        # Handle line endings
        lines = []
        while b'\n' in buffer:
            pos = buffer.find(b'\n')
            lines.append(buffer[:pos])
            buffer = buffer[pos+1:]

        if buffer and not buffer.endswith(b'\r\n') and not buffer.endswith(b'\n'):
            lines.append(buffer)
            buffer = b""

        # Process lines
        for line in lines:
            if line.endswith(b'\r'):
                line = line[:-1]

            if not line:
                # Empty line - dispatch event
                if data_lines:
                    events.append(' '.join(data_lines))
                    data_lines = []
                    if events[-1] == '[DONE]':
                        return events[:-1]
            else:
                # Check for data field
                if line.startswith(b'data:'):
                    data = line[5:].lstrip()
                    if data:
                        data_lines.append(data.decode('utf-8', errors='ignore'))
                    else:
                        data_lines.append('')

    # Handle final event if terminated properly
    if data_lines and buffer == b'':
        events.append(' '.join(data_lines))

    return events

def retry_delay(attempt, base, cap):
    if attempt < 0 or base < 0 or cap < 0:
        raise ValueError("All arguments must be nonnegative")

    if attempt >= 10**9:
        return cap

    # Handle special cases where base or cap is 0
    if base == 0:
        return 0.0
    if cap == 0:
        return 0.0

    # Calculate base * 2**attempt without constructing huge integers
    # We'll use the fact that 2**attempt can be computed efficiently
    delay = base * (1 << attempt)  # This is equivalent to base * 2**attempt

    # Check if we would exceed cap
    if delay > cap:
        return cap

    return delay

def fifo_admit(active, queued, budget, slots):
    # Check if any queued request exceeds the budget
    for req in queued:
        if req > budget:
            raise ValueError("Any queued reservation exceeds the whole budget")

    # Initialize result lists
    admitted = []
    remaining = []

    # Track current usage
    active_tokens = sum(active)
    active_slots = len(active)

    # Process queued requests in FIFO order
    for request in queued:
        if (active_slots < slots and active_tokens + request <= budget):
            # Admit the request
            admitted.append(request)
            active_tokens += request
            active_slots += 1
        else:
            # Reject the request
            remaining.append(request)

    return (admitted, remaining)
